//#region src/lib/messaging.ts
async function sendToActiveTab(msg) {
	const [tab] = await chrome.tabs.query({
		active: true,
		currentWindow: true
	});
	if (!tab?.id) throw new Error("No active tab found");
	try {
		await chrome.tabs.sendMessage(tab.id, { type: "PING" });
	} catch (err) {
		throw new Error("Vecta AI is not active on this page. Please refresh the page and try again.");
	}
	await chrome.tabs.sendMessage(tab.id, msg);
}
async function getJobDetailsFromActiveTab() {
	const [tab] = await chrome.tabs.query({
		active: true,
		currentWindow: true
	});
	if (!tab?.id) throw new Error("No active tab found");
	try {
		await chrome.tabs.sendMessage(tab.id, { type: "PING" });
	} catch (err) {
		throw new Error("Vecta AI content script is not loaded. Please refresh the page.");
	}
	return await chrome.tabs.sendMessage(tab.id, { type: "GET_JOB_DETAILS" });
}
